raw_output:
SELECT 100.0 * SUM(CASE WHEN c.isOnlineOnly = 1 THEN 1 ELSE 0 END) / COUNT(*)
FROM cards c
WHERE c.uuid IN (SELECT uuid FROM foreign_data WHERE language = 'Portuguese (Brazil)');

