raw_output:
SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.remaining < 0 THEN b.link_to_event END) / COUNT(DISTINCT e.event_id) AS percentage
FROM event e
LEFT JOIN budget b ON b.link_to_event = e.event_id;

